create extension if not exists pgcrypto;
create table if not exists public.profiles(id uuid primary key references auth.users(id) on delete cascade,full_name text,language text not null default 'en' check(language in('en','ar')),created_at timestamptz not null default now());
create table if not exists public.courses(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,name text not null,code text,difficulty text not null default 'Medium' check(difficulty in('Easy','Medium','Hard')),progress int not null default 0 check(progress between 0 and 100),total_units int not null default 10,completed_units int not null default 0,created_at timestamptz not null default now());
create table if not exists public.exams(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,course_id uuid references public.courses(id) on delete set null,title text not null,exam_date date not null,readiness int not null default 0 check(readiness between 0 and 100),created_at timestamptz not null default now());
create table if not exists public.study_sessions(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,course_id uuid references public.courses(id) on delete set null,planned_minutes int not null default 50,actual_minutes int not null default 0,topic text,difficulty int check(difficulty between 1 and 5),status text not null default 'planned' check(status in('planned','completed','missed')),starts_at timestamptz,completed_at timestamptz,created_at timestamptz not null default now());
create table if not exists public.plan_events(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,event_type text not null,reason text,payload jsonb not null default '{}'::jsonb,created_at timestamptz not null default now());
DO $$ DECLARE t text; BEGIN FOR t IN SELECT unnest(ARRAY['profiles','courses','exams','study_sessions','plan_events']) LOOP EXECUTE format('alter table public.%I enable row level security',t); END LOOP; END $$;
create policy if not exists "profiles own" on public.profiles for all using(auth.uid()=id) with check(auth.uid()=id);
create policy if not exists "courses own" on public.courses for all using(auth.uid()=user_id) with check(auth.uid()=user_id);
create policy if not exists "exams own" on public.exams for all using(auth.uid()=user_id) with check(auth.uid()=user_id);
create policy if not exists "sessions own" on public.study_sessions for all using(auth.uid()=user_id) with check(auth.uid()=user_id);
create policy if not exists "events own" on public.plan_events for all using(auth.uid()=user_id) with check(auth.uid()=user_id);
create index if not exists courses_user_idx on public.courses(user_id); create index if not exists exams_user_date_idx on public.exams(user_id,exam_date); create index if not exists sessions_user_start_idx on public.study_sessions(user_id,starts_at);
